<script lang="ts">import UnavailableChart from './UnavailableChart.svelte'; import type { Pip, Unavailable } from './types'; let { data }: { data: Pip[] | Unavailable } = $props(); const max = $derived(Array.isArray(data) ? Math.max(1,...data.flatMap(d=>[d.pips,d.sources,d.recommended_sources])) : 1);</script><figure class="chart"><h3>Pips vs sources</h3>{#if !Array.isArray(data)}<UnavailableChart reason={data.reason}/>{:else}<p class="chart-legend">Outline: pips · solid: sources · dashed: recommended</p>{#each data as row}<div class="chart-row"><span class="mono">{row.color}</span><svg viewBox="0 0 260 30" role="img" aria-label={`${row.color}: ${row.pips} pips, ${row.sources} sources, ${row.recommended_sources} recommended`}><rect x="1" y="3" width={row.pips/max*240} height="9" class="outline-bar"/><rect x="1" y="17" width={row.sources/max*240} height="9" class="data-bar"/><line x1={1+row.recommended_sources/max*240} x2={1+row.recommended_sources/max*240} y1="0" y2="30" class="target-line"/></svg><span class="mono">{row.pips}/{row.sources}/{row.recommended_sources}</span></div>{/each}{/if}</figure>